import fs from 'node:fs';
import path from 'node:path';

// Check rendered production output, including cross-page invariants. No packages required.
const destination = path.resolve(process.argv[2] || 'public');
const base = new URL(process.env.SITE_BASE_URL || 'https://marouanedaoudi.github.io/');
// Separate project repository hosted on the same GitHub Pages origin, verified live.
// It is not generated by this portfolio's Hugo build.
const independentProjectPaths = ['/slitherlink-shiny/'];
const errors = [];
const fail = (file, message) => errors.push(`${path.relative(destination, file) || '.'}: ${message}`);
const decode = value => value.replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)));
const attr = (tag, name) => {
  const expression = new RegExp(`(?:\\s|^)${name}\\s*=\\s*(?:"([^"]*)"|'([^']*)'|([^\\s>]+))`, 'i');
  const match = expression.exec(tag);
  return match ? decode(match[1] ?? match[2] ?? match[3] ?? '') : null;
};
const tags = (html, name) => [...html.matchAll(new RegExp(`<${name}\\b[^>]*>`, 'gi'))].map(match => match[0]);
const walk = directory => fs.readdirSync(directory, {withFileTypes: true}).flatMap(entry => {
  const file = path.join(directory, entry.name);
  return entry.isDirectory() ? walk(file) : [file];
});
if (!fs.existsSync(destination)) throw new Error(`Build directory missing: ${destination}`);
const files = walk(destination);
const documents = new Map();
const localFile = url => {
  let pathname;
  try { pathname = decodeURIComponent(url.pathname); } catch { return null; }
  const relative = pathname.startsWith(base.pathname) ? pathname.slice(base.pathname.length) : pathname.replace(/^\//, '');
  const target = path.resolve(destination, relative);
  if (target !== destination && !target.startsWith(destination + path.sep)) return null;
  if (fs.existsSync(target) && fs.statSync(target).isFile()) return target;
  const index = path.join(target, 'index.html');
  return fs.existsSync(index) ? index : null;
};
const pageURL = file => {
  const relative = path.relative(destination, file).split(path.sep).join('/').replace(/index\.html$/, '');
  return new URL(relative, base);
};

for (const file of files.filter(file => file.endsWith('.html'))) {
  const html = fs.readFileSync(file, 'utf8');
  // The ownership verification response is not a web page.
  if (path.basename(file).startsWith('google') && html.startsWith('google-site-verification:')) continue;
  const url = pageURL(file);
  const meta = tags(html, 'meta');
  const links = tags(html, 'link');
  const redirect = meta.find(tag => attr(tag, 'http-equiv')?.toLowerCase() === 'refresh');
  if (redirect) {
    const target = /url\s*=\s*(.+)$/i.exec(attr(redirect, 'content') || '')?.[1];
    if (target && !localFile(new URL(target, url))) fail(file, `redirect target does not exist: ${target}`);
    continue;
  }
  const metaValue = (name, property = 'name') => meta.filter(tag => attr(tag, property)?.toLowerCase() === name).map(tag => attr(tag, 'content'));
  const canonical = links.filter(tag => attr(tag, 'rel') === 'canonical').map(tag => attr(tag, 'href'));
  const noindex = metaValue('robots').some(value => value?.includes('noindex'));
  const alternates = new Map(links.filter(tag => attr(tag, 'rel') === 'alternate' && attr(tag, 'hreflang')).map(tag => [attr(tag, 'hreflang'), attr(tag, 'href')]));
  const lang = attr(tags(html, 'html')[0] || '', 'lang');
  const ids = new Set(tags(html, '[a-z][a-z0-9:-]*').map(tag => attr(tag, 'id')).filter(Boolean));
  const title = decode(/<title[^>]*>([\s\S]*?)<\/title>/i.exec(html)?.[1] || '').trim();
  if (!title || !title.includes('Marouane Daoudi')) fail(file, 'title must identify Marouane Daoudi');
  if (metaValue('description').length !== 1 || !metaValue('description')[0]?.trim()) fail(file, 'exactly one nonempty description is required');
  if (canonical.length !== 1 || canonical[0] !== url.href) fail(file, `canonical must be exactly ${url.href}; found ${canonical.join(', ')}`);
  if (!['en', 'fr'].includes(lang)) fail(file, 'html lang must be en or fr');
  if (tags(html, 'h1').length !== 1) fail(file, 'expected exactly one H1');
  if (url.pathname.endsWith('/404.html') && !noindex) fail(file, '404 must be noindex');
  if (/\/(?:tags|categories)(?:\/|$)/.test(url.pathname) && !noindex) fail(file, 'taxonomy pages must be noindex');
  if (!noindex) {
    if (alternates.get(lang) !== url.href) fail(file, 'hreflang must include the current page');
    if (!alternates.has('x-default')) fail(file, 'hreflang x-default is missing');
    if (alternates.get('x-default')?.includes('/fr/')) fail(file, 'x-default must point to an English page');
    for (const [language, href] of alternates) {
      if (!href?.startsWith(base.href)) fail(file, `hreflang ${language} must be an absolute production URL`);
      if (!localFile(new URL(href, url))) fail(file, `hreflang ${language} target missing: ${href}`);
    }
    for (const name of ['og:title', 'og:description', 'og:image', 'og:url']) if (metaValue(name, 'property').length !== 1) fail(file, `missing or duplicated ${name}`);
    if (metaValue('og:url', 'property')[0] !== url.href) fail(file, 'og:url must equal the canonical');
    if (metaValue('twitter:card')[0] !== 'summary_large_image') fail(file, 'social card missing');
    const schemas = [...html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi)].filter(match => attr(match[1], 'type') === 'application/ld+json');
    if (schemas.length !== 1) fail(file, 'expected exactly one JSON-LD graph');
    for (const match of schemas) {
      try {
        const schema = JSON.parse(match[2]);
        if (schema['@context'] !== 'https://schema.org' || !Array.isArray(schema['@graph'])) throw new Error('invalid JSON-LD graph');
        const graph = schema['@graph'];
        const person = graph.find(item => item['@type'] === 'Person');
        if (person?.name !== 'Marouane Daoudi' || !person.sameAs?.includes('https://github.com/marouanedaoudi')) throw new Error('verified Person identity missing');
        if (url.pathname === '/' || url.pathname === '/fr/') {
          if (!graph.some(item => item['@type'] === 'ProfilePage')) throw new Error('home ProfilePage missing');
        } else if (!graph.some(item => item['@type'] === 'BreadcrumbList')) throw new Error('breadcrumb schema missing');
        if (graph.some(item => item['@type'] === 'ScholarlyArticle')) throw new Error('do not describe student projects as scholarly publications');
      } catch (error) { fail(file, `JSON-LD: ${error.message}`); }
    }
  }
  documents.set(file, {file, html, url, lang, ids, noindex, alternates, title});
}

const titles = new Map();
for (const document of documents.values()) {
  const {file, html, url, ids, noindex, alternates, title, lang} = document;
  if (!noindex) {
    const titleKey = `${lang}\0${title}`;
    if (titles.has(titleKey)) fail(file, `duplicate indexable title also used by ${path.relative(destination, titles.get(titleKey))}`);
    titles.set(titleKey, file);
    for (const [language, href] of alternates) {
      if (language === 'x-default') continue;
      const other = documents.get(localFile(new URL(href, url)));
      if (!other || other.alternates.get(lang) !== url.href) fail(file, `hreflang reciprocity missing for ${language}`);
    }
  }
  for (const tag of tags(html, '(?:a|img|script|link|source)')) {
    const raw = attr(tag, 'href') ?? attr(tag, 'src');
    if (!raw || /^(?:mailto:|tel:|data:|javascript:)/i.test(raw)) continue;
    let target;
    try { target = new URL(raw, url); } catch { fail(file, `invalid URL: ${raw}`); continue; }
    if (target.origin !== base.origin) continue;
    if (independentProjectPaths.some(prefix => target.pathname === prefix.slice(0, -1) || target.pathname.startsWith(prefix))) continue;
    const targetFile = localFile(target);
    if (!targetFile) { fail(file, `internal target missing: ${raw}`); continue; }
    if (target.hash && targetFile.endsWith('.html')) {
      const other = documents.get(targetFile);
      let anchor;
      try { anchor = decodeURIComponent(target.hash.slice(1)); } catch { fail(file, `invalid anchor: ${raw}`); continue; }
      if (other && anchor && !other.ids.has(anchor)) fail(file, `internal anchor missing: ${raw}`);
    }
  }
}

// Read both sitemap indexes and urlsets. Every indexable HTML page must appear once.
const sitemapURLs = new Set();
for (const file of files.filter(file => path.basename(file) === 'sitemap.xml')) {
  const xml = fs.readFileSync(file, 'utf8');
  const isIndex = /<sitemapindex\b/.test(xml);
  for (const match of xml.matchAll(/<loc>([^<]+)<\/loc>/g)) {
    const href = decode(match[1]);
    if (!href.startsWith(base.href)) fail(file, `nonproduction sitemap URL: ${href}`);
    const targetFile = localFile(new URL(href));
    if (!targetFile) fail(file, `sitemap target missing: ${href}`);
    if (!isIndex) {
      if (sitemapURLs.has(href)) fail(file, `duplicate sitemap URL: ${href}`);
      sitemapURLs.add(href);
      if (documents.get(targetFile)?.noindex) fail(file, `noindex page is in sitemap: ${href}`);
    }
  }
}
for (const {file, url, noindex} of documents.values()) if (!noindex && !sitemapURLs.has(url.href)) fail(file, 'indexable page missing from sitemap');

const inbound = new Set();
for (const {html, url} of documents.values()) for (const tag of tags(html, 'a')) {
  const href = attr(tag, 'href');
  if (!href) continue;
  try {
    const target = new URL(href, url);
    if (target.origin === base.origin) inbound.add(localFile(target));
  } catch {}
}
for (const {file, noindex, url} of documents.values()) if (!noindex && !['/', '/fr/'].includes(url.pathname) && !inbound.has(file)) fail(file, 'indexable page has no internal incoming link');

for (const relative of ['index.json', 'fr/index.json']) {
  const file = path.join(destination, relative);
  try {
    const data = JSON.parse(fs.readFileSync(file, 'utf8'));
    if (!Array.isArray(data) || data.length === 0) throw new Error('expected nonempty search array');
    for (const entry of data) {
      const href = entry.permalink || entry.url || entry.relpermalink;
      if (!entry.title || !href || !localFile(new URL(href, base))) throw new Error('search entry must have a title and existing page URL');
    }
  } catch (error) { fail(file, `local search: ${error.message}`); }
}

const robotsFile = path.join(destination, 'robots.txt');
if (!fs.existsSync(robotsFile) || !fs.readFileSync(robotsFile, 'utf8').includes(`Sitemap: ${new URL('sitemap.xml', base).href}`)) fail(robotsFile, 'robots sitemap declaration missing');
const verification = path.join(destination, 'google27cb935313f9e2a6.html');
if (!fs.existsSync(verification) || fs.readFileSync(verification, 'utf8').trim() !== 'google-site-verification: google27cb935313f9e2a6.html') fail(verification, 'original Google verification response changed or missing');
const social = path.join(destination, 'images/social.png');
if (!fs.existsSync(social)) fail(social, 'social preview missing');
else {
  const bytes = fs.readFileSync(social);
  if (bytes.toString('hex', 0, 8) !== '89504e470d0a1a0a' || bytes.readUInt32BE(16) !== 1200 || bytes.readUInt32BE(20) !== 630) fail(social, 'social preview must be a 1200×630 PNG');
}

if (errors.length) {
  console.error(`Website validation failed (${errors.length} issues):\n${errors.map(error => `- ${error}`).join('\n')}`);
  process.exitCode = 1;
} else {
  console.log(`Validated ${documents.size} HTML pages, ${sitemapURLs.size} indexable URLs, bilingual metadata, internal links and anchors, structured data, search data and social assets.`);
}
